VALUES ('club_opelika-bamboo-belles', 'Bamboo Belles', 'opelika-bamboo-belles', 'Plays American Mahjong only: its site states that all classes, open play, leagues and events follow the National Mah Jongg League rules and the current official NMJL card. Hosts open play at local venues such as Cakeitecture Bakery, Resting Pulse Brewing Company and Peppertree Steaks n'' Wine.', (SELECT id FROM City WHERE name = 'Opelika' AND state = 'AL'), NULL, 'https://bamboo-belles.bamgoodtime.com', NULL, NULL, NULL, NULL, 1, 0, 1, 1, 0, 0, NULL, 'Open play at local venues most weeks (dates listed on the club site)', 'https://bamboo-belles.bamgoodtime.com', '2026-10-11', 'ACTIVE')
